        {
            std::cout << "RunBotanProviderEncryptDecryptBufferTest: FAILED cancel status=" << cancelStatus << std::endl;
            return UNEXPECTED_ERROR;
        }

        std::cout << "RunBotanProviderEncryptDecryptBufferTest: PASSED cancellation" << std::endl;
        return NO_ERROR;
