            {
                input[index] = static_cast<short>((index - 25) * 1000);
            }
            input[0] = SHRT_MIN;
            input[49] = SHRT_MAX;

            short output[50] = {};
            const bool ok = RoundTripBytes(cryptoApi, password, passwordSize, input, 50, output);
            std::cout << "  short[50] -> " << (ok ? "OK" : "FAILED") << std::endl;
